class Solution:
    def decodeCiphertext(self, encodedText: str, rows: int) -> str:
        n = len(encodedText)
        if n == 0:
            return ""
        cols = n // rows
        grid = [encodedText[r * cols:(r + 1) * cols] for r in range(rows)]
        res = []
        for d in range(cols):
            for r in range(rows):
                if r + d < cols:
                    res.append(grid[r][r + d])
        return "".join(res).rstrip(" ")

