var decodeCiphertext = function(encodedText, rows) {
    const n = encodedText.length;
    if (n === 0) return "";
    const cols = Math.floor(n / rows);
    const grid = [];
    for (let r = 0; r < rows; r++) grid.push(encodedText.slice(r * cols, (r + 1) * cols));
    const res = [];
    for (let d = 0; d < cols; d++)
        for (let r = 0; r < rows; r++)
            if (r + d < cols) res.push(grid[r][r + d]);
    return res.join("").replace(/ +$/, "");
};

